async def act(page):
    import asyncio

    """
    From the current page state (root with a visible popup), perform the following new actions:
    1) Click the "Sample Page" link (visible in the document) to go to the page that likely contains the site's search UI.
    2) Dismiss any visible dialog/alertdialog overlays (click a close-style button inside them).
    3) Locate an accessible search input (prefer role="complementary" -> role="searchbox" -> role="textbox").
    4) Fill it with 'GPT' and trigger the search (prefer clicking a search-named button inside the complementary region, otherwise press Enter).
    5) Wait for results in role="main" and click the first link inside the third role="article" child (or click the article itself if no link exists).

    Notes:
    - Every locator.nth() is guarded by a preceding await locator.count() call.
    - The final click (which may navigate away) is the last action in this function.
    """

    # 1) Click the "Sample Page" link
    sample_link = page.get_by_role("link", name="Sample Page")
    try:
        if await sample_link.count() > 0:
            # Use nth(0) for clarity/robustness
            await sample_link.nth(0).click()
            try:
                await page.wait_for_load_state("networkidle", timeout=3000)
            except Exception:
                # small pause if networkidle not reached
                await asyncio.sleep(0.5)
    except Exception:
        # If clicking the Sample Page link fails, continue from current state
        pass

    # 2) Dismiss any visible dialogs/alertdialogs that might block the UI
    for dlg_role in ("dialog", "alertdialog"):
        dlg_locator = page.get_by_role(dlg_role)
        try:
            dlg_count = await dlg_locator.count()
        except Exception:
            dlg_count = 0
        for i in range(dlg_count):
            dlg = dlg_locator.nth(i)
            # Try to find and click a close-like button inside the dialog
            btns = dlg.get_by_role("button")
            try:
                btn_count = await btns.count()
            except Exception:
                btn_count = 0
            closed = False
            for bi in range(btn_count):
                btn = btns.nth(bi)
                name = ""
                try:
                    name = (await btn.inner_text()).strip()
                except Exception:
                    try:
                        name = (await btn.get_attribute("aria-label")) or ""
                    except Exception:
                        name = ""
                if any(tok in name.lower() for tok in ("close", "dismiss", "ok", "×", "x", "✖")):
                    try:
                        await btn.click()
                        closed = True
                        await asyncio.sleep(0.25)
                        break
                    except Exception:
                        pass
            if closed:
                continue
            # fallback: click first button if present
            if btn_count > 0:
                try:
                    await btns.nth(0).click()
                    await asyncio.sleep(0.25)
                except Exception:
                    pass

    # 3) Locate the search input (prefer complementary -> searchbox -> textbox; fall back to global)
    search_input = None
    comp = page.get_by_role("complementary")
    try:
        comp_count = await comp.count()
    except Exception:
        comp_count = 0

    if comp_count > 0:
        try:
            comp_searchboxes = comp.get_by_role("searchbox")
            if await comp_searchboxes.count() > 0:
                search_input = comp_searchboxes.nth(0)
        except Exception:
            pass
        if search_input is None:
            try:
                comp_textboxes = comp.get_by_role("textbox")
                if await comp_textboxes.count() > 0:
                    search_input = comp_textboxes.nth(0)
            except Exception:
                pass

    # Global fallbacks
    if search_input is None:
        try:
            global_sb = page.get_by_role("searchbox")
            if await global_sb.count() > 0:
                search_input = global_sb.nth(0)
        except Exception:
            pass

    if search_input is None:
        try:
            global_tb = page.get_by_role("textbox")
            tb_count = await global_tb.count()
        except Exception:
            global_tb = page.get_by_role("textbox")
            try:
                tb_count = await global_tb.count()
            except Exception:
                tb_count = 0
        if tb_count > 0:
            # prefer a textbox with placeholder/aria-label containing 'search'
            found = False
            for i in range(tb_count):
                candidate = global_tb.nth(i)
                label = ""
                try:
                    label = (await candidate.get_attribute("placeholder")) or ""
                except Exception:
                    label = ""
                if not label:
                    try:
                        label = (await candidate.get_attribute("aria-label")) or ""
                    except Exception:
                        label = ""
                if "search" in (label or "").lower():
                    search_input = candidate
                    found = True
                    break
            if not found:
                try:
                    search_input = global_tb.nth(0)
                except Exception:
                    search_input = None

    if search_input is None:
        raise Exception("Could not find a search input to perform search for 'GPT'.")

    # 4) Fill the search input with 'GPT'
    try:
        await search_input.fill("GPT")
    except Exception:
        try:
            await search_input.focus()
            await page.keyboard.type("GPT")
        except Exception:
            pass

    # Try to find a search-triggering button inside the complementary region (preferred)
    search_button = None
    if comp_count > 0:
        try:
            comp_buttons = comp.get_by_role("button")
            comp_btn_count = await comp_buttons.count()
        except Exception:
            comp_buttons = None
            comp_btn_count = 0
        if comp_buttons is not None and comp_btn_count > 0:
            for bi in range(comp_btn_count):
                try:
                    b = comp_buttons.nth(bi)
                    b_name = ""
                    try:
                        b_name = (await b.inner_text()).strip()
                    except Exception:
                        try:
                            b_name = (await b.get_attribute("aria-label")) or ""
                        except Exception:
                            b_name = ""
                    if "search" in (b_name or "").lower():
                        search_button = b
                        break
                except Exception:
                    continue
            if search_button is None and comp_btn_count > 0:
                try:
                    search_button = comp_buttons.nth(0)
                except Exception:
                    search_button = None

    # Page-wide fallback: any button with 'search' in its name
    if search_button is None:
        all_buttons = page.get_by_role("button")
        try:
            total_buttons = await all_buttons.count()
        except Exception:
            total_buttons = 0
        for i in range(total_buttons):
            try:
                b = all_buttons.nth(i)
                b_name = ""
                try:
                    b_name = (await b.inner_text()).strip()
                except Exception:
                    try:
                        b_name = (await b.get_attribute("aria-label")) or ""
                    except Exception:
                        b_name = ""
                if "search" in (b_name or "").lower():
                    search_button = b
                    break
            except Exception:
                continue

    # Trigger the search: prefer clicking the identified button, otherwise press Enter
    triggered = False
    if search_button is not None:
        try:
            await search_button.click()
            triggered = True
        except Exception:
            triggered = False

    if not triggered:
        try:
            await search_input.press("Enter")
            triggered = True
        except Exception:
            try:
                await search_input.focus()
                await page.keyboard.press("Enter")
                triggered = True
            except Exception:
                triggered = False

    # 5) Wait for results in role="main" and click the third result
    main = page.get_by_role("main")
    try:
        await main.wait_for(timeout=5000)
    except Exception:
        await asyncio.sleep(0.5)

    articles = main.get_by_role("article")
    try:
        article_count = await articles.count()
    except Exception:
        article_count = 0

    if article_count < 3:
        raise Exception(f"Expected at least 3 search results, found {article_count}")

    third_article = articles.nth(2)
    links_in_third = third_article.get_by_role("link")
    try:
        links_count = await links_in_third.count()
    except Exception:
        links_count = 0

    if links_count > 0:
        # Final action: click the first link inside the third article
        await links_in_third.nth(0).click()
    else:
        # Fallback final action: click the article itself
        await third_article.click()

